export const normalize=v=>String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
export const escapeHTML=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function safeURL(value){try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password?u.href:'';}catch{return '';}}
export function combinations(values,size=2){if(size===0)return [[]];return values.flatMap((v,i)=>combinations(values.slice(i+1),size-1).map(rest=>[v,...rest]));}
export function toggleSelection(values,id,limit){if(values.includes(id))return values.filter(x=>x!==id);return values.length<limit?[...values,id]:values;}
export const formatNumber=n=>n===null||n===undefined||n===''?'Non publié':new Intl.NumberFormat('fr-FR').format(n);
export const formatPct=n=>n===null||n===undefined||n===''?'Non publié':new Intl.NumberFormat('fr-FR',{maximumFractionDigits:1}).format(n)+' %';
export function filterFormations(rows,filters={}){const tokens=normalize(filters.q).split(/\s+/).filter(Boolean);return rows.filter(r=>{if(filters.academy&&filters.academy!==r.academy)return false;if(filters.family&&filters.family!==r.family)return false;if(filters.status&&filters.status!==r.status)return false;if(filters.savedOnly&&!filters.savedIds?.includes(r.id))return false;return tokens.every(t=>(r._search??normalize([r.title,r.school,r.city,r.department,r.family,r.detail].join(' '))).includes(t));});}

export function newProject(){return {schemaVersion:2,level:'seconde',currentPath:'generale',stmgSpecific:'',name:'',classroom:'',title:'Mon projet d’orientation',interests:'',strengths:'',values:'',experiences:'',questions:'',specialtyReason:'',option:'',mobility:'',support:'',nextStep:'',meeting:'',motivation:'',target:'',reorientation:'',techSeries:'',activeScenarioId:'',trio:[],pair:[],domainIds:[],pathways:[],options:[],establishments:[],scenarios:[],choices:[],resources:[],tasks:[],checks:{},budget:{rent:'',food:'',transport:'',other:'',income:'',oneoff:''},updatedAt:new Date().toISOString()};}
const textFields=['currentPath','stmgSpecific','name','classroom','title','interests','strengths','values','experiences','questions','specialtyReason','option','mobility','support','nextStep','meeting','motivation','target','reorientation','techSeries','activeScenarioId'];
const idPattern=/^[a-z0-9_-]{1,60}$/i;
export function validateProject(obj){
  if(!obj||typeof obj!=='object'||Array.isArray(obj)||![1,2].includes(obj.schemaVersion))throw new Error('Ce fichier n’est pas un projet Mon parcours compatible (formats 1 ou 2).');
  const out=newProject();
  if(['seconde','premiere','terminale'].includes(obj.level))out.level=obj.level;
  for(const k of textFields){if(obj[k]!==undefined&&typeof obj[k]!=='string')throw new Error('Champ texte incorrect : '+k);out[k]=String(obj[k]??out[k]).slice(0,15000);}
  if(!['generale','stmg','technologique','professionnelle'].includes(out.currentPath))out.currentPath='generale';
  if(!['','gf','mercatique','rhc'].includes(out.stmgSpecific))out.stmgSpecific='';
  for(const key of ['trio','pair','resources','domainIds','pathways','options']){if(obj[key]!==undefined&&!Array.isArray(obj[key]))throw new Error('Liste incorrecte : '+key);const max=key==='trio'?3:key==='pair'?2:100;out[key]=[...new Set((obj[key]??[]).filter(x=>typeof x==='string'&&idPattern.test(x)))].slice(0,max);}
  if(obj.establishments!==undefined&&!Array.isArray(obj.establishments))throw new Error('Liste d’établissements incorrecte.');
  out.establishments=[...new Set((obj.establishments??[]).filter(x=>typeof x==='string').map(x=>x.slice(0,500)))].slice(0,40);
  if(obj.scenarios!==undefined&&!Array.isArray(obj.scenarios))throw new Error('Liste de scénarios incorrecte.');
  out.scenarios=(obj.scenarios??[]).slice(0,3).filter(s=>s&&typeof s==='object').map((s,i)=>({id:typeof s.id==='string'&&idPattern.test(s.id)?s.id:'scenario-'+i,title:String(s.title??`Scénario ${String.fromCharCode(65+i)}`).slice(0,120),domainIds:[...new Set((Array.isArray(s.domainIds)?s.domainIds:[]).filter(x=>typeof x==='string'&&idPattern.test(x)))].slice(0,10),trio:[...new Set((Array.isArray(s.trio)?s.trio:[]).filter(x=>typeof x==='string'&&idPattern.test(x)))].slice(0,3),pair:[...new Set((Array.isArray(s.pair)?s.pair:[]).filter(x=>typeof x==='string'&&idPattern.test(x)))].slice(0,2),stmgSpecific:['gf','mercatique','rhc'].includes(s.stmgSpecific)?s.stmgSpecific:'',techSeries:typeof s.techSeries==='string'?s.techSeries.slice(0,60):'',pathway:typeof s.pathway==='string'?s.pathway.slice(0,60):'',notes:String(s.notes??'').slice(0,6000)}));
  if(obj.choices!==undefined&&!Array.isArray(obj.choices))throw new Error('Liste de formations incorrecte.');
  out.choices=(obj.choices??[]).slice(0,60).filter(x=>x&&typeof x==='object'&&typeof x.id==='string').map(c=>({id:c.id.slice(0,90),title:String(c.title??'').slice(0,500),school:String(c.school??'').slice(0,400),city:String(c.city??'').slice(0,200),url:safeURL(c.url),source:String(c.source??'').slice(0,150),reason:String(c.reason??'').slice(0,6000),question:String(c.question??'').slice(0,3000),motivation:String(c.motivation??'').slice(0,15000),status:['À explorer','À approfondir','Candidature envisagée','Candidature confirmée','Proposition reçue','Proposition acceptée','Non retenue'].includes(c.status)?c.status:'À explorer'}));
  out.choices=out.choices.filter((c,i,a)=>a.findIndex(v=>v.id===c.id)===i);
  if(obj.tasks!==undefined&&!Array.isArray(obj.tasks))throw new Error('Liste d’actions incorrecte.');
  out.tasks=(obj.tasks??[]).slice(0,100).filter(t=>t&&typeof t==='object').map((t,i)=>({id:'task-'+i,text:String(t.text??'').slice(0,1200),date:/^\d{4}-\d{2}-\d{2}$/.test(t.date)?t.date:'',done:t.done===true}));
  for(const k of Object.keys(out.budget)){const v=obj.budget?.[k];if(v!==null&&v!==undefined&&v!==''&&Number.isFinite(Number(v))&&Number(v)>=0&&Number(v)<=100000)out.budget[k]=String(v);}
  if(obj.checks&&typeof obj.checks==='object'&&!Array.isArray(obj.checks))for(const[k,v]of Object.entries(obj.checks))if(/^(seconde-[0-4]|(premiere|terminale)(-(generale|stmg|technologique|professionnelle))?-[0-4])$/.test(k))out.checks[k]=v===true;
  if(typeof obj.updatedAt==='string'&&!Number.isNaN(Date.parse(obj.updatedAt)))out.updatedAt=obj.updatedAt;
  return out;
}

export function budgetSummary(b){const keys=['rent','food','transport','other'];const number=k=>b[k]===''||b[k]===undefined?0:Number(b[k]);return {monthly:keys.reduce((t,k)=>t+number(k),0),income:number('income'),gap:keys.reduce((t,k)=>t+number(k),0)-number('income'),oneoff:number('oneoff'),oneoffProvided:b.oneoff!==''&&b.oneoff!==undefined,provided:keys.filter(k=>b[k]!==''&&b[k]!==undefined).length,incomeProvided:b.income!==''&&b.income!==undefined};}
export function progressSections(p){return [Boolean(p.interests||p.strengths||p.values||p.domainIds?.length),Boolean(p.trio.length||p.pair.length||p.specialtyReason||p.techSeries||p.stmgSpecific),Boolean(p.choices.length||p.target||p.scenarios?.length),Boolean(p.experiences),Boolean(p.mobility||p.support||budgetSummary(p.budget).provided||budgetSummary(p.budget).incomeProvided||budgetSummary(p.budget).oneoffProvided),Boolean(p.nextStep||p.tasks.length||p.meeting)].filter(Boolean).length;}

export function analyzeScenario(trio,pair,domainIds,rules={},specialties=[]){
  const kept=pair.map(id=>specialties.find(s=>s.id===id)?.short??id);
  const abandoned=trio.filter(id=>!pair.includes(id));
  const abandonedNames=abandoned.map(id=>specialties.find(s=>s.id===id)?.short??id);
  const selected=domainIds.map(id=>({id,...(rules[id]??{})})).filter(d=>d.label);
  const coherent=selected.filter(d=>pair.some(id=>(d.strong??[]).includes(id)));
  const partial=selected.filter(d=>!coherent.includes(d)&&pair.some(id=>(d.helpful??[]).includes(id)));
  const vigilance=selected.filter(d=>!coherent.includes(d)&&!partial.includes(d));
  const options=[];
  if(!pair.includes('maths')&&selected.some(d=>d.math==='helpful'||d.math==='strong'))options.push({id:'math-comp',label:'Mathématiques complémentaires',level:'À examiner attentivement',why:'Le projet sélectionné comporte des raisonnements quantitatifs, des statistiques ou des sciences. Cette option peut maintenir un enseignement mathématique en terminale. Elle n’est pas proposée par automatisme et ne remplace pas la spécialité mathématiques.'});
  if(pair.includes('maths')&&selected.some(d=>d.math==='strong'))options.push({id:'math-exp',label:'Mathématiques expertes',level:'À explorer',why:'Le projet sélectionné peut mener vers des cursus fortement mathématisés. Un approfondissement peut être utile si le goût pour les mathématiques et la charge de travail envisagée le permettent. Cette option n’est ni une garantie ni une obligation générale.'});
  return {kept,abandoned,abandonedNames,coherent,partial,vigilance,options,strengths:coherent.length?coherent.map(d=>`${d.label} : les enseignements conservés offrent des appuis directement liés au domaine.`):['Cette paire permet de poursuivre une réflexion large. Sa cohérence dépendra surtout des formations précisément explorées.'],warnings:vigilance.length?vigilance.map(d=>`${d.label} : le parcours reste possible, mais il faut examiner attentivement les contenus, attendus et critères de chaque formation.`):['Aucune incompatibilité automatique n’est déduite. Il reste utile de comparer plusieurs fiches officielles.'],consequences:`Conserver ${kept.join(' et ')||'ces enseignements'}${abandonedNames.length?' et arrêter '+abandonedNames.join(' et '):''} approfondit certains apprentissages sans créer, à lui seul, un droit ou une interdiction d’accès à une formation.`};
}

const printFrame=(title,body,source='')=>`<article class="print-document"><header class="print-cover"><img class="print-logo" src="./assets/logo-horizontal.jpg" alt="Lycée Ambroise Paré · Laval"><p class="print-label">Lycée Ambroise Paré · Mon parcours</p><h1>${escapeHTML(title)}</h1><p class="print-date">Généré le ${new Date().toLocaleDateString('fr-FR')}</p></header>${body}${source?`<footer class="print-source">${escapeHTML(source)}</footer>`:''}<p class="print-note">Site propriété du Lycée Ambroise Paré · Laval.</p><div class="print-page-number" aria-hidden="true"></div></article>`;
export function projectHTML(p,specialties=[],resources=[],domains=[],rules={},offers=[]){
 const e=escapeHTML,names=ids=>(ids||[]).map(id=>specialties.find(s=>s.id===id)?.short??id).join(' + ');
 const block=(label,value)=>String(value??'').trim()?`<div class="print-block"><h3>${e(label)}</h3><p>${e(value)}</p></div>`:'';
 const link=(u,label)=>safeURL(u)?`<p><a href="${e(safeURL(u))}">${e(label||u)}</a></p>`:'';
 const budget=budgetSummary(p.budget),parts=[],add=(title,body)=>{if(body.trim())parts.push({title,body});};
 const pathNames={generale:'Voie générale',technologique:'Voie technologique',professionnelle:'Voie professionnelle'};
 const currentNames={generale:'Voie générale',stmg:'STMG',technologique:'Autre série technologique',professionnelle:'Voie professionnelle / réorientation'};
 const specificNames={gf:'Gestion et finance',mercatique:'Mercatique',rhc:'Ressources humaines et communication'};
 const analysis=(p.level==='seconde'||p.currentPath==='generale')&&p.domainIds.length>0&&p.trio.length===3&&p.pair.length===2?analyzeScenario(p.trio,p.pair,p.domainIds,rules,specialties):null;
 add('Ce qui m’intéresse',block('Mes intérêts',p.interests)+block('Mes points d’appui',p.strengths)+block('Ce qui compte pour moi',p.values)+block('Domaines explorés',p.domainIds.map(id=>domains.find(d=>d.id===id)?.title??id).join(' · ')));
 add('Parcours et choix envisagés',block('Parcours actuel',p.level==='seconde'?'Seconde générale et technologique':currentNames[p.currentPath]||'À préciser')+block('Voies explorées',(p.pathways||[]).map(id=>pathNames[id]??id).join(' · '))+(p.currentPath==='stmg'?block('Enseignement spécifique STMG',specificNames[p.stmgSpecific]||'À explorer'):'')+block('Trio général exploré',names(p.trio))+block('Paire générale envisagée ou suivie',names(p.pair))+(analysis?block('Spécialité arrêtée dans cette hypothèse',analysis.abandonedNames.join(' · ')):'')+block('Série technologique explorée',p.techSeries.toUpperCase())+block('Hypothèse de réorientation',p.reorientation)+block('Options et dispositifs envisagés',[...(p.options||[]).map(id=>offers.find(o=>o.id===id)?.title??id),p.option].filter(Boolean).join(' · '))+block('Mes raisons et les points à travailler',p.specialtyReason));
 if(analysis)add('Lecture de mon hypothèse',block('Des appuis à explorer',analysis.strengths.join('\n'))+block('Des points à vérifier',analysis.warnings.join('\n'))+block('Ce qui change',analysis.consequences)+(analysis.options.length?block('Options à examiner',analysis.options.map(o=>o.label+' · '+o.why).join('\n')):'')+'<p class="print-note">Ces repères pédagogiques ne prédisent pas une admission. Vérifier les attendus et critères des formations.</p>');
 add('Mes scénarios enregistrés',(p.scenarios||[]).map(s=>`<section class="print-item"><h3>${e(s.title)}</h3>${block('Enseignements',s.pair?.length?names(s.pair):s.techSeries?s.techSeries.toUpperCase()+(s.stmgSpecific?' · '+(specificNames[s.stmgSpecific]||''):''):pathNames[s.pathway]||s.pathway||'À préciser')}${block('Domaines',s.domainIds.map(id=>domains.find(d=>d.id===id)?.title??id).join(' · '))}${block('Mes notes',s.notes)}</section>`).join(''));
 const choices=p.choices.map(c=>`<section class="print-item"><h3>${e(c.title)}</h3><p>${e([c.school,c.city].filter(Boolean).join(' · '))}<br>État renseigné : ${e(c.status||'À explorer')}</p>${c.source?`<p class="print-note">${e(c.source)}</p>`:''}${block('Pourquoi cette piste m’intéresse',c.reason)}${block('Ce que je dois vérifier',c.question)}${block('Mon brouillon de motivation',c.motivation)}${link(c.url,'Consulter la fiche source')}</section>`).join('');
 add('Mes pistes de formation',block('Mon idée du moment',p.target)+choices+block('Établissements repérés',(p.establishments||[]).join('\n')));
 add('Mes expériences et ma présentation',block('Expériences, lectures et découvertes',p.experiences)+block('Mon texte personnel',p.motivation));
 if(p.mobility||p.support||budget.provided||budget.incomeProvided||budget.oneoffProvided)add('Les conditions pour réussir',block('Mobilité et organisation',p.mobility)+block('Aides ou accompagnements à rechercher',p.support)+(budget.provided||budget.incomeProvided||budget.oneoffProvided?`<p>Budget estimatif : ${budget.provided}/4 postes mensuels renseignés. Dépenses mensuelles saisies : ${formatNumber(budget.monthly)} €. ${budget.incomeProvided?'Ressources mensuelles estimées : '+formatNumber(budget.income)+' €. Écart dépenses moins ressources : '+formatNumber(budget.gap)+' €.':'Ressources non renseignées.'} Frais ponctuels saisis : ${formatNumber(budget.oneoff)} €.</p><p class="print-note">Estimation personnelle à vérifier. Une aide estimée n’est pas une aide accordée.</p>`:'<p class="print-note">Budget non renseigné.</p>'));
 add('Mes prochaines étapes',block('Mes questions',p.questions)+block('Ma prochaine action',p.nextStep)+block('Ce que je retiens d’un échange',p.meeting)+(p.tasks.length?`<ul class="print-tasks">${p.tasks.map(t=>`<li>${t.done?'☑':'☐'} ${e(t.text||'Action à préciser')}${t.date?' · '+e(t.date.split('-').reverse().join('/')):''}</li>`).join('')}</ul>`:''));
 add('Ressources repérées',p.resources.map(id=>resources.find(r=>r.id===id)).filter(Boolean).map(r=>link(r.url,r.title+' · '+r.provider)).join(''));
 const body=`<p>${e(p.name||'Projet personnel')} · ${e({seconde:'Seconde',premiere:'Première',terminale:'Terminale'}[p.level])}${p.classroom?' · '+e(p.classroom):''}</p><p class="print-note">Document de travail personnel. Il ne constitue ni une candidature ni un engagement d’admission. L’élève choisit à qui il le transmet. Les rubriques non renseignées sont omises.</p>${parts.map((part,i)=>`<section class="print-section"><h2>${String(i+1).padStart(2,'0')} · ${e(part.title)}</h2>${part.body}</section>`).join('')}`;
 return printFrame(p.title||'Mon projet d’orientation',body,'Mon parcours · contenus vérifiés le 16 octobre 2026. Catalogue historique Parcoursup 2025 hors apprentissage : vérifier la session en cours.');
}

export function formationHTML(r){
  const e=escapeHTML,official=safeURL(r.url)?`<p><a href="${e(r.url)}">Consulter la fiche officielle Parcoursup</a></p>`:'';
  const body=`<p><strong>${e(r.school)}</strong><br>${e(r.city)} · Académie de ${e(r.academy)}</p><section class="print-section"><h2>Présentation</h2><p>${e(r.detail||r.title)}</p><p>${e(r.status)} · ${e(r.selectivity)}</p></section><section class="print-section"><h2>Modalités d’accès et repères 2025</h2><table class="print-table"><tbody><tr><th>Places</th><td>${formatNumber(r.places)}</td></tr><tr><th>Candidats en phase principale</th><td>${formatNumber(r.candidates)}</td></tr><tr><th>Propositions pendant la campagne</th><td>${formatNumber(r.proposals)}</td></tr><tr><th>Acceptations pendant la campagne</th><td>${formatNumber(r.accepted)}</td></tr><tr><th>Taux d’accès publié</th><td>${formatPct(r.access)}</td></tr></tbody></table><p class="print-note">Le taux d’accès est un indicateur descriptif de la campagne. Il ne donne pas une probabilité personnelle.</p></section><section class="print-section"><h2>Profils observés parmi les acceptations</h2><table class="print-table"><tbody><tr><th>Néo-bacheliers généraux</th><td>${formatNumber(r.general)}</td></tr><tr><th>Néo-bacheliers technologiques</th><td>${formatNumber(r.techno)}</td></tr><tr><th>Néo-bacheliers professionnels</th><td>${formatNumber(r.pro)}</td></tr><tr><th>Boursiers parmi les néo-bacheliers admis</th><td>${formatPct(r.scholarship)}</td></tr><tr><th>Femmes parmi l’ensemble des admis</th><td>${formatPct(r.women)}</td></tr></tbody></table><p class="print-note">Une majorité observée n’est ni une condition d’accès ni la preuve qu’un profil est obligatoire. L’extrait ne contient pas les spécialités ni les moyennes individuelles.</p></section><section class="print-section"><h2>À vérifier pour la session en cours</h2><ul><li>contenus et organisation des enseignements</li><li>attendus et critères d’examen des candidatures</li><li>frais, aides et modalités d’inscription</li><li>poursuites d’études, débouchés, contacts et journées portes ouvertes</li></ul>${official}</section>`;
  return printFrame(r.title,body,'Source : Parcoursup — traitement SIES, campagne 2025 hors apprentissage. Fiche officielle à vérifier pour la session en cours.');
}

export function guideHTML(g,resources=[],updated=''){
 const e=escapeHTML;
 const links=g.resources.map(id=>resources.find(r=>r.id===id)).filter(Boolean).map(r=>safeURL(r.url)?`<p><a href="${e(safeURL(r.url))}">${e(r.title)} · ${e(r.provider)}</a></p>`:'').join('');
 return printFrame(g.title,`<p>${e(g.subtitle)}</p><ol>${g.items.map(t=>`<li>${e(t)}</li>`).join('')}</ol><h2>À retenir</h2><p>${e(g.end)}</p><h2>Ressources</h2>${links}`,`Préparé le ${updated}. Vérifier les consignes officielles de sa session.`);
}
